function partition(array, low_index, high_index) {
    const pivot = array[high_index];
    let i = low_index - 1;
    const j = low_index;

    for (let k = low_index; k < high_index; k++)
        if (array[k] <= pivot) {
            i++;
            [array[i], array[k]] = [array[k], array[i]];
        }
    [array[i + 1], array[high_index]] = [array[high_index], array[i + 1]];
    return i + 1;
}

function quickSort(array, low_index = 0, high_index = array.length - 1) {
    const pivot_index = partition(array, low_index, high_index);
    if (pivot_index > 0) {
        quickSort(array, low_index, pivot_index - 1);
    }
    if (array.length > pivot_index + 1) {
        quickSort(array, pivot_index + 1, high_index);
    }
}

